import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';

interface VirtualScrollProps<T> {
  items: T[];
  itemHeight: number | ((index: number, item: T) => number);
  containerHeight: number;
  renderItem: (item: T, index: number) => React.ReactNode;
  overscan?: number;
  getItemKey?: (item: T, index: number) => string;
  onScroll?: (scrollTop: number) => void;
}

// Virtual scroll implementation for large message lists
export function VirtualScroll<T>({
  items,
  itemHeight,
  containerHeight,
  renderItem,
  overscan = 5,
  getItemKey,
  onScroll,
}: VirtualScrollProps<T>) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);

  // Calculate item heights with validation
  const getItemHeight = useCallback((index: number, item: T): number => {
    let height: number;
    if (typeof itemHeight === 'function') {
      height = itemHeight(index, item);
    } else {
      height = itemHeight;
    }
    // Validate height - prevent 0, negative, or NaN
    if (!height || height <= 0 || isNaN(height)) {
      return 50; // Default fallback height
    }
    return height;
  }, [itemHeight]);

  // Calculate total height and item positions
  const { itemPositions, totalHeight } = useMemo(() => {
    const positions: number[] = [];
    let height = 0;

    items.forEach((item, index) => {
      positions.push(height);
      height += getItemHeight(index, item);
    });

    return { itemPositions: positions, totalHeight: height };
  }, [items, getItemHeight]);

  // Find visible range using binary search
  const findVisibleRange = useCallback((scrollTop: number) => {
    const viewportBottom = scrollTop + containerHeight;

    // Find start index (first item that overlaps viewport)
    let startIndex = 0;
    for (let i = 0; i < itemPositions.length; i++) {
      const pos = itemPositions[i];
      const h = getItemHeight(i, items[i]);
      if (pos + h > scrollTop) {
        startIndex = Math.max(0, i - overscan);
        break;
      }
    }

    // Find end index (last item that overlaps viewport)
    let endIndex = items.length - 1;
    for (let i = startIndex; i < itemPositions.length; i++) {
      const pos = itemPositions[i];
      if (pos >= viewportBottom) {
        endIndex = Math.min(items.length - 1, i + overscan);
        break;
      }
    }

    return { startIndex, endIndex };
  }, [items, itemPositions, containerHeight, overscan, getItemHeight]);

  // Get visible range
  const visibleRange = findVisibleRange(scrollTop);
  const visibleCount = visibleRange.endIndex - visibleRange.startIndex + 1;

  // Handle scroll event
  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    const newScrollTop = e.currentTarget.scrollTop;
    setScrollTop(newScrollTop);
    onScroll?.(newScrollTop);
  }, [onScroll]);

  // Render visible items with performance indicator
  return (
    <div
      ref={containerRef}
      onScroll={handleScroll}
      style={{
        height: containerHeight,
        overflow: 'auto',
        position: 'relative',
      }}
      className="scrollbar-thin scrollbar-thumb-muted scrollbar-track-transparent"
    >
      {/* Performance indicator (show rendered count) */}
      {items.length > 50 && (
        <div className="sticky top-0 right-0 float-right p-2 z-10 bg-background/80 backdrop-blur-sm rounded-bl-lg">
          <div className="text-xs text-green-500 px-2 py-1 bg-green-500/10 rounded">
            <span>⚡</span>
            <span className="ml-1 font-mono">{visibleCount}/{items.length}</span>
            <span className="ml-1">渲染</span>
          </div>
        </div>
      )}

      <div style={{ height: totalHeight, position: 'relative' }}>
        {items.slice(visibleRange.startIndex, visibleRange.endIndex + 1).map((item, idx) => {
          const actualIndex = visibleRange.startIndex + idx;
          const key = getItemKey ? getItemKey(item, actualIndex) : `item-${actualIndex}`;
          const position = itemPositions[actualIndex];

          return (
            <div
              key={key}
              style={{
                position: 'absolute',
                top: position,
                width: '100%',
              }}
            >
              {renderItem(item, actualIndex)}
            </div>
          );
        })}
      </div>
    </div>
  );
}